_SOURCE_PREVIEW_MEDIA_TYPES = {
    "pdf": "application/pdf",
    "jpeg": "image/jpeg",
    "png": "image/png",
    "mp3": "audio/mpeg",
    "ogg": "audio/ogg",
    "wav": "audio/wav",
    "mp4": "video/mp4",
    "webm": "video/webm",
}
_MAX_SOURCE_MEDIA_RANGE_BYTES = 32 * 1024 * 1024
_MAX_SOURCE_MEDIA_DURATION_MS = 24 * 60 * 60 * 1000


@dataclass(frozen=True, slots=True)
class PreviewVariantProjection:
    id: UUID | None
    kind: str
    media_type: str
    delivery: str
    content_url: str
    renderer_contract: str
    rank: int
    byte_size: int | None
    width: int | None
    height: int | None
    duration_ms: int | None
    page_count: int | None
    source: str
    provider_id: str | None = None
    provider_version: str | None = None
    codecs: tuple[str, ...] | None = None
    authored_overlay: bool = False
    content_revision: str | None = None

    def to_payload(self) -> dict[str, object]:
        payload: dict[str, object] = {
            "id": self.id,
            "kind": self.kind,
            "media_type": self.media_type,
            "delivery": self.delivery,
            "content_url": self.content_url,
            "renderer_contract": self.renderer_contract,
            "rank": self.rank,
            "byte_size": self.byte_size,
            "width": self.width,
            "height": self.height,
            "duration_ms": self.duration_ms,
            "page_count": self.page_count,
            "source": self.source,
            "provider_id": self.provider_id,
            "provider_version": self.provider_version,
        }
        if self.codecs is not None:
            payload["codecs"] = self.codecs
        return payload


@dataclass(frozen=True, slots=True)
class SourcePreviewPresentation:
    kind: str
    media_type: str
    delivery: str
    renderer_contract: str
    width: int | None = None
    height: int | None = None
    duration_ms: int | None = None
    codecs: tuple[str, ...] | None = None


@dataclass(frozen=True, slots=True)
class PreviewManifestProjection:
    status: str
    version_id: UUID
    selected_preview_attempt_id: UUID | None
    variants: tuple[PreviewVariantProjection, ...]
    unavailable_reason: str | None
    download_url: str | None
    is_current_preview: bool
    etag: str

    def to_payload(self) -> dict[str, object]:
        return {
            "schema_version": "1",
            "status": self.status,
            "version_id": self.version_id,
            "selected_preview_attempt_id": self.selected_preview_attempt_id,
            "variants": tuple(variant.to_payload() for variant in self.variants),
            "fallbacks": ("metadata", "download"),
            "unavailable_reason": self.unavailable_reason,
            "download_url": self.download_url,
            "is_current_preview": self.is_current_preview,
        }


class LibraryPreviewManifestService:
    """Resolve Preview presentation without exposing storage identity."""

    def __init__(
        self,
        *,
        store_for: Callable[[UUID], FilesystemLibraryBlobStore],
        blob_repository_factory: LibraryBlobRepositoryFactory,
        max_http_range_bytes: int = DEFAULT_MAX_HTTP_RANGE_BYTES,
    ) -> None:
        if max_http_range_bytes <= 0:
            raise ValueError("max_http_range_bytes must be positive")
        # D-5: resolved per call, not cached -- see LibraryContentService.
        self._store_for = store_for
        self._blob_repository_factory = blob_repository_factory
        self._max_http_range_bytes = max_http_range_bytes
        self._library_content = LibraryContentService(
            store_for=store_for,
            blob_repository_factory=blob_repository_factory,
            max_http_range_bytes=max_http_range_bytes,
        )

    def resolve_manifest(
        self,
        *,
        session: Session,
        workspace_id: UUID,
        version_id: UUID,
        actor: ActorContext,
    ) -> PreviewManifestProjection:
        item, version = self._authorize_version(
            session=session,
            workspace_id=workspace_id,
            version_id=version_id,
            actor=actor,
        )
        variants: list[PreviewVariantProjection] = []
        selected_attempt = self._selected_preview_attempt(
            session,
            item=item,
            version=version,
        )
        stale_dependency = False
        if selected_attempt is not None:
            if self._dependency_matches(session, version, selected_attempt):
                variants.extend(
                    self._generated_variants(
                        session,
                        workspace_id=workspace_id,
                        item=item,
                        version=version,
                        attempt=selected_attempt,
                    )
                )
            else:
                stale_dependency = True
                selected_attempt = None

        canonical = get_canonical_library_version(session, item)
        if canonical is not None and canonical.id == version.id:
            variants.extend(
                self._semantic_variants(
                    session,
                    workspace_id=workspace_id,
                    item=item,
                    version=version,
                )
            )
        source_variant = self._source_variant(
            session,
            workspace_id=workspace_id,
            item=item,
            version=version,
        )
        if source_variant is not None:
            variants.append(source_variant)
        variants = _deduplicate_variants(variants)
        aggregate_status = _manifest_status(
            has_variants=bool(variants),
            preview_status=version.preview_status,
        )
        unavailable_reason = None
        if not variants:
            unavailable_reason = (
                "stale_dependency" if stale_dependency else _unavailable_reason(version)
            )
        etag = _manifest_etag(
            actor=actor,
            membership_role=_membership_role(session, actor, workspace_id),
            item=item,
            version=version,
            selected_attempt_id=(selected_attempt.id if selected_attempt else None),
            variant_keys=[
                (
                    variant.source,
                    str(variant.id),
                    variant.renderer_contract,
                    variant.rank,
                    variant.content_revision,
                )
                for variant in variants
            ],
        )
        return PreviewManifestProjection(
            status=aggregate_status,
            version_id=version.id,
            selected_preview_attempt_id=(
                selected_attempt.id if selected_attempt is not None else None
            ),
            variants=tuple(variants),
            unavailable_reason=unavailable_reason,
            download_url=library_original_content_url(
                workspace_id=workspace_id,
                version_id=version.id,
                source_blob_id=version.source_blob_id,
            ),
            is_current_preview=item.current_preview_version_id == version.id,
            etag=etag,
        )

    def resolve_source_content(
        self,
        *,
        session: Session,
        workspace_id: UUID,
        version_id: UUID,
        actor: ActorContext,
        range_header: str | None = None,
        if_range_header: str | None = None,
    ) -> LibraryOriginalContent:
        """Resolve an allowlisted original for the isolated Preview transport.

        This capability is deliberately narrower than the attachment-only
        original download.  It reauthorizes the exact Workspace/item/version
        lineage and admits only source formats whose browser renderer contract
        is explicitly server-owned.
        """

        item, version = self._authorize_version(
            session=session,
            workspace_id=workspace_id,
            version_id=version_id,
            actor=actor,
        )
        presentation = _source_preview_presentation(version)
        blob = self._source_blob_if_available(
            session,
            workspace_id=workspace_id,
            version=version,
        )
        if presentation is None or blob is None:
            raise ReadNotFoundError("Library Preview source content not found")

        content = self._library_content.resolve_original(
            session=session,
            workspace_id=workspace_id,
            library_item_id=item.id,
            version_id=version_id,
            actor=actor,
            range_header=None,
            if_range_header=None,
        )
        expected_media_type = presentation.media_type
        if (
            content.workspace_id != workspace_id
            or content.library_item_id != item.id
            or content.version_id != version.id
            or content.media_type != expected_media_type
            or content.byte_size != blob.byte_size
            or content.sha256 != blob.sha256.value
        ):
            raise LibraryContentIntegrityError()

        etag = _source_content_etag(
            actor=actor,
            membership_role=_membership_role(session, actor, workspace_id),
            item=item,
            version=version,
            blob=blob.reference,
            media_type=expected_media_type,
        )
        effective_range = (
            range_header if if_range_allows_range(if_range_header, etag) else None
        )
        try:
            source_media = presentation.kind in {"audio", "video"}
            byte_range = parse_http_byte_range(
                effective_range,
                complete_length=content.byte_size,
                max_range_bytes=(
                    _MAX_SOURCE_MEDIA_RANGE_BYTES
                    if source_media
                    else self._max_http_range_bytes
                ),
                clamp_open_ended=source_media,
            )
        except ByteRangeNotSatisfiable as exc:
            raise LibraryByteRangeError(
                complete_length=exc.complete_length
            ) from exc
        return replace(content, etag=etag, byte_range=byte_range)

    @staticmethod
    def _authorize_version(
        *,
        session: Session,
        workspace_id: UUID,
        version_id: UUID,
        actor: ActorContext,
    ) -> tuple[LibraryItem, LibraryItemVersion]:
        """Flat lookup (P9.2): the item is derived from the version, not
        carried in the URL."""

        check_actor_can_access(actor, workspace_id, "read", session=session)
        version = get_in_workspace(
            session,
            LibraryItemVersion,
            workspace_id=workspace_id,
            resource_id=version_id,
        )
        if version is None:
            raise ReadNotFoundError("Library Preview not found")
        item = get_in_workspace(
            session,
            LibraryItem,
            workspace_id=workspace_id,
            resource_id=version.library_item_id,
        )
        if item is None or item.lifecycle_status in EXCLUDED_LIBRARY_LIFECYCLE_STATUSES:
            raise ReadNotFoundError("Library Preview not found")
        if not actor_can_read_library_trust_level(item.trust_level, actor):
            raise RejectedByPolicyError(
                "restricted source requires elevated access",
                error_code="restricted_library_denied",
            )
        visible_heads = {
            item.current_version_id,
            item.current_ready_version_id,
            item.current_preview_version_id,
        }
        if version.id not in visible_heads:
            raise ReadNotFoundError("Library Preview not found")
        return item, version

    @staticmethod
    def _selected_preview_attempt(
        session: Session,
        *,
        item: LibraryItem,
        version: LibraryItemVersion,
    ) -> LibraryAttempt | None:
        if (
            item.current_preview_version_id != version.id
            or version.selected_preview_attempt_id is None
            or version.preview_status not in {"ready", "ready_partial"}
        ):
            return None
        attempt = session.get(
            LibraryAttempt,
            version.selected_preview_attempt_id,
        )
        if (
            attempt is None
            or attempt.stage != "preview_generation"
            or attempt.library_item_version_id != version.id
            or attempt.status != "completed"
        ):
            return None
        return attempt

    def _generated_variants(
        self,
        session: Session,
        *,
        workspace_id: UUID,
        item: LibraryItem,
        version: LibraryItemVersion,
        attempt: LibraryAttempt,
    ) -> list[PreviewVariantProjection]:
        rows = session.scalars(
            select(LibraryArtifact)
            .join(
                LibraryArtifactPreviewDetail,
                LibraryArtifactPreviewDetail.artifact_id == LibraryArtifact.id,
            )
            .where(
                LibraryArtifact.attempt_id == attempt.id,
                LibraryArtifact.library_item_version_id == version.id,
                LibraryArtifact.stage == "preview_generation",
            )
            .order_by(
                LibraryArtifactPreviewDetail.rank.asc(),
                LibraryArtifact.ordinal.asc(),
                LibraryArtifact.id.asc(),
            )
        )
        variants: list[PreviewVariantProjection] = []
        for artifact in rows:
            detail = artifact.preview_detail
            if not renderer_accepts_media_type(
                detail.renderer_contract,
                artifact.media_type,
            ):
                continue
            try:
                self._preview_artifact_blob(
                    session,
                    workspace_id=workspace_id,
                    artifact=artifact,
                )
            except ReadServiceError:
                continue
            variants.append(
                PreviewVariantProjection(
                    id=artifact.id,
                    kind=artifact.kind,
                    media_type=artifact.media_type,
                    delivery=detail.delivery,
                    content_url=_artifact_content_url(workspace_id, artifact.id),
                    renderer_contract=detail.renderer_contract,
                    rank=detail.rank,
                    byte_size=artifact.byte_size,
                    width=detail.width,
                    height=detail.height,
                    duration_ms=detail.duration_ms,
                    page_count=detail.page_count,
                    source="generated",
                    provider_id=attempt.provider_id,
                    provider_version=attempt.provider_version,
                )
            )
        return variants

    def _semantic_variants(
        self,
        session: Session,
        *,
        workspace_id: UUID,
        item: LibraryItem,
        version: LibraryItemVersion,
    ) -> list[PreviewVariantProjection]:
        variants: list[PreviewVariantProjection] = []
        effective = get_effective_library_markdown(session, version)
        overlay = effective.overlay if effective is not None else None
        if overlay is not None:
            variants.append(
                PreviewVariantProjection(
                    id=overlay.id,
                    kind="markdown",
                    media_type="text/markdown",
                    delivery="text",
                    content_url=_semantic_overlay_content_url(
                        workspace_id,
                        overlay.id,
                    ),
                    renderer_contract="core.markdown.v1",
                    rank=0,
                    byte_size=overlay.byte_size,
                    width=None,
                    height=None,
                    duration_ms=None,
                    page_count=None,
                    source="semantic",
                    authored_overlay=True,
                    content_revision=(
                        f"{overlay.revision}:{overlay.content_sha256}"
                    ),
                )
            )
        for artifact in list_canonical_library_artifacts(session, version):
            if (
                overlay is not None
                and effective is not None
                and artifact.id == effective.base_artifact.id
            ):
                continue
            presentation = _semantic_presentation(version, artifact)
            if presentation is None or not self._library_artifact_available(
                session,
                workspace_id=workspace_id,
                artifact=artifact,
            ):
                continue
            kind, renderer_contract, delivery, rank = presentation
            variants.append(
                PreviewVariantProjection(
                    id=artifact.id,
                    kind=kind,
                    media_type=artifact.media_type or "application/octet-stream",
                    delivery=delivery,
                    content_url=_artifact_content_url(workspace_id, artifact.id),
                    renderer_contract=renderer_contract,
                    rank=rank,
                    byte_size=artifact.byte_size,
                    width=None,
                    height=None,
                    duration_ms=None,
                    page_count=None,
                    source="semantic",
                )
            )
            if renderer_contract == "core.table.v1":
                variants.append(
                    PreviewVariantProjection(
                        id=artifact.id,
                        kind="markdown",
                        media_type=artifact.media_type
                        or "application/octet-stream",
                        delivery="text",
                        content_url=_artifact_content_url(workspace_id, artifact.id),
                        renderer_contract="core.markdown.v1",
                        rank=rank + 100,
                        byte_size=artifact.byte_size,
                        width=None,
                        height=None,
                        duration_ms=None,
                        page_count=None,
                        source="semantic",
                    )
                )
        return variants

    def _source_variant(
        self,
        session: Session,
        *,
        workspace_id: UUID,
        item: LibraryItem,
        version: LibraryItemVersion,
    ) -> PreviewVariantProjection | None:
        presentation = _source_preview_presentation(version)
        if presentation is None or self._source_blob_if_available(
            session,
            workspace_id=workspace_id,
            version=version,
        ) is None:
            return None
        return PreviewVariantProjection(
            id=None,
            kind=presentation.kind,
            media_type=presentation.media_type,
            delivery=presentation.delivery,
            content_url=_source_content_url(workspace_id, version.id),
            renderer_contract=presentation.renderer_contract,
            rank=200,
            byte_size=version.byte_size,
            width=presentation.width,
            height=presentation.height,
            duration_ms=presentation.duration_ms,
            page_count=None,
            source="original",
            codecs=presentation.codecs,
        )

    def _source_blob_if_available(self, session, *, workspace_id, version):
        if (
            version.source_blob_workspace_id != workspace_id
            or version.source_blob_id is None
            or version.source_blob_epoch is None
            or version.byte_size is None
        ):
            return None
        expected_media_type = _SOURCE_PREVIEW_MEDIA_TYPES.get(version.format_id)
        if (
            expected_media_type is None
            or version.detected_media_type != expected_media_type
        ):
            return None
        reference = BlobReference(
            workspace_id=workspace_id,
            blob_id=version.source_blob_id,
            epoch=BlobEpoch(version.source_blob_epoch),
        )
        if _security_blocked(session, reference):
            return None
        blob = self._blob_repository_factory(session).get(reference)
        if (
            blob is None
            or blob.sha256.value != version.content_hash.lower()
            or blob.byte_size != version.byte_size
            or blob.media_type != expected_media_type
        ):
            return None
        try:
            store = self._store_for(workspace_id)
            expected_keys = {
                store.storage_key_for_hash(workspace_id, blob.sha256.value),
                store.blob_key(
                    blob.reference,
                    blob.sha256,
                    publish_generation=1,
                ).value,
            }
        except LibraryBlobStorageError:
            return None
        return blob if blob.storage_key in expected_keys else None

    def _library_artifact_available(
        self,
        session,
        *,
        workspace_id,
        artifact,
    ) -> bool:
        if (
            artifact.blob_workspace_id != workspace_id
            or artifact.blob_id is None
            or artifact.blob_epoch is None
            or artifact.content_sha256 is None
            or artifact.byte_size is None
            or artifact.media_type is None
        ):
            return False
        reference = BlobReference(
            workspace_id=workspace_id,
            blob_id=artifact.blob_id,
            epoch=BlobEpoch(artifact.blob_epoch),
        )
        if _security_blocked(session, reference):
            return False
        blob = self._blob_repository_factory(session).get(reference)
        return (
            blob is not None
            and blob.sha256.value == artifact.content_sha256.lower()
            and blob.byte_size == artifact.byte_size
            and blob.media_type == artifact.media_type
        )

    def _preview_artifact_blob(self, session, *, workspace_id, artifact):
        if artifact.blob_workspace_id != workspace_id:
            raise ReadNotFoundError("Library Preview content not found")
        reference = BlobReference(
            workspace_id=workspace_id,
            blob_id=artifact.blob_id,
            epoch=BlobEpoch(artifact.blob_epoch),
        )
        if _security_blocked(session, reference):
            raise ReadNotFoundError("Library Preview content not found")
        blob = self._blob_repository_factory(session).get(reference)
        if blob is None:
            raise LibraryContentIntegrityError()
        if (
            blob.sha256.value != artifact.content_sha256.lower()
            or blob.byte_size != artifact.byte_size
            or blob.media_type != artifact.media_type
        ):
            raise LibraryContentIntegrityError()
        try:
            expected_key = self._store_for(workspace_id).blob_key(
                blob.reference,
                blob.sha256,
                publish_generation=1,
            ).value
        except LibraryBlobStorageError as exc:
            raise LibraryContentIntegrityError() from exc
        if blob.storage_key != expected_key:
            raise LibraryContentIntegrityError()
        return blob

    @staticmethod
    def _dependency_matches(
        session: Session,
        version: LibraryItemVersion,
        attempt: LibraryAttempt,
    ) -> bool:
        return preview_generation_dependency_matches(session, version, attempt)


def _semantic_presentation(version, artifact):
    media_type = artifact.media_type
    if media_type == "text/markdown" and artifact.role in {"markdown", "search_text"}:
        if version.format_id in {"csv", "tsv", "xlsx"}:
            return "table", "core.table.v1", "text", 110
        return "markdown", "core.markdown.v1", "text", 100
    if media_type == "text/plain" and artifact.role in {"markdown", "search_text"}:
        return "text", "core.text.v1", "text", 100
    if media_type == "application/json" and artifact.role == "metadata":
        return "metadata", "core.metadata.v1", "text", 300
    if media_type == "application/pdf" and artifact.role == "preview":
        return "pdf", "core.pdf.v1", "range", 100
    if media_type and media_type.startswith("image/") and artifact.role == "preview":
        if renderer_accepts_media_type("core.image.v1", media_type):
            return "image", "core.image.v1", "inline", 100
    return None


def _source_preview_presentation(version: LibraryItemVersion):
    media_type = _SOURCE_PREVIEW_MEDIA_TYPES.get(version.format_id)
    if media_type is None or version.detected_media_type != media_type:
        return None
    if version.format_id == "pdf":
        return SourcePreviewPresentation(
            kind="pdf",
            media_type=media_type,
            delivery="range",
            renderer_contract="core.pdf.v1",
        )

    expected_profile = SOURCE_PREVIEW_IMAGE_PROFILES.get(version.format_id)
    detection = version.detection_json
    container = detection.get("container") if isinstance(detection, dict) else None
    if expected_profile is not None:
        if (
            not isinstance(container, dict)
            or container.get("validator") != "image"
            or container.get("valid") is not True
            or container.get("source_preview_profile") != expected_profile
        ):
            return None
        width = container.get("width")
        height = container.get("height")
        pixel_count = container.get("pixel_count")
        if (
            type(width) is not int
            or type(height) is not int
            or type(pixel_count) is not int
            or not 0 < width <= MAX_SOURCE_PREVIEW_IMAGE_DIMENSION
            or not 0 < height <= MAX_SOURCE_PREVIEW_IMAGE_DIMENSION
            or not 0 < pixel_count <= MAX_SOURCE_PREVIEW_IMAGE_PIXELS
            or width * height != pixel_count
        ):
            return None
        return SourcePreviewPresentation(
            kind="image",
            media_type=media_type,
            delivery="inline",
            renderer_contract="core.image.v1",
            width=width,
            height=height,
        )

    expected_media_profiles = SOURCE_PREVIEW_MEDIA_PROFILES.get(version.format_id)
    if (
        expected_media_profiles is None
        or not isinstance(container, dict)
        or container.get("valid") is not True
        or container.get("validator") not in expected_media_profiles
    ):
        return None
    kind = "audio" if media_type.startswith("audio/") else "video"
    return SourcePreviewPresentation(
        kind=kind,
        media_type=media_type,
        delivery="range",
        renderer_contract=f"core.{kind}.v1",
        duration_ms=_source_media_duration_ms(container),
        codecs=_source_media_codecs(version.format_id, container),
    )


def _source_media_duration_ms(container: dict[str, object]) -> int | None:
    value = container.get("duration_seconds")
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not 0 < value <= _MAX_SOURCE_MEDIA_DURATION_MS / 1000
    ):
        return None
    return max(1, round(value * 1000))


def _source_media_codecs(
    format_id: str,
    container: dict[str, object],
) -> tuple[str, ...]:
    raw_values = container.get("codecs")
    if not isinstance(raw_values, list):
        codec = container.get("codec")
        raw_values = [codec] if isinstance(codec, str) else []
    aliases = {
        "V_VP8": "vp8",
        "V_VP9": "vp9",
        "V_AV1": "av01",
    }
    values: list[str] = []
    for raw in raw_values[:16]:
        if not isinstance(raw, str):
            continue
        value = aliases.get(raw, raw).strip()
        if (
            value in {"", "unknown", "pcm", "ieee-float"}
            or value.startswith("wave-format-")
            or value.startswith("mpeg-")
            or value.startswith("0x")
            or len(value) > 64
            or not value.isascii()
            or any(not (char.isalnum() or char in "._- ") for char in value)
        ):
            continue
        if value not in values:
            values.append(value)
    # Bare audio/mpeg and audio/wav are the interoperable browser probes. Their
    # validator codec labels are operational facts, not RFC 6381 codec strings.
    if format_id in {"mp3", "wav"}:
        return ()
    return tuple(values)


def _manifest_status(*, has_variants: bool, preview_status: str) -> str:
    if has_variants:
        return "ready_partial" if preview_status == "ready_partial" else "ready"
    if preview_status in {
        "queued",
        "generating",
        "failed",
        "timed_out",
    }:
        return preview_status
    return "unavailable"


def _unavailable_reason(version: LibraryItemVersion) -> str:
    if version.preview_status in {"queued", "generating"}:
        return "preview_pending"
    if version.preview_status in {"failed", "timed_out"}:
        return "preview_provider_failed"
    return "preview_provider_unavailable"


def _deduplicate_variants(
    variants: list[PreviewVariantProjection],
) -> list[PreviewVariantProjection]:
    ordered = sorted(
        variants,
        key=lambda value: (
            not value.authored_overlay,
            value.rank,
            value.source != "generated",
            str(value.id),
        ),
    )
    seen: set[tuple[str, str]] = set()
    result: list[PreviewVariantProjection] = []
    for variant in ordered:
        key = (variant.renderer_contract, variant.content_url)
        if key in seen:
            continue
        seen.add(key)
        result.append(variant)
    return result


def _membership_role(session, actor, workspace_id):
    if actor.user_id is None:
        return None
    membership = session.get(WorkspaceMembership, (actor.user_id, workspace_id))
    return membership.role if membership is not None else None


def _manifest_etag(
    *,
    actor,
    membership_role,
    item,
    version,
    selected_attempt_id,
    variant_keys,
) -> str:
    return _opaque_etag(
        {
            "schema": "library-preview-manifest-v1",
            "actor": _actor_etag_facts(actor, membership_role),
            "association": {
                "workspace_id": str(item.workspace_id),
                "item_id": str(item.id),
                "version_id": str(version.id),
                "selected_preview_attempt_id": _str_or_none(selected_attempt_id),
                "current_preview_version_id": _str_or_none(
                    item.current_preview_version_id
                ),
                "lifecycle_status": item.lifecycle_status,
                "trust_level": item.trust_level,
                "variant_keys": variant_keys,
            },
        },
        prefix="lib-preview-manifest-v1",
    )


def _content_etag(
    *,
    actor,
    membership_role,
    item,
    version,
    attempt,
    artifact,
    blob,
) -> str:
    return _opaque_etag(
        {
            "schema": "library-preview-content-v1",
            "actor": _actor_etag_facts(actor, membership_role),
            "association": {
                "workspace_id": str(item.workspace_id),
                "item_id": str(item.id),
                "version_id": str(version.id),
                "attempt_id": str(attempt.id),
                "artifact_id": str(artifact.id),
                "blob_id": str(blob.blob_id),
                "blob_epoch": blob.epoch.value,
                "lifecycle_status": item.lifecycle_status,
                "trust_level": item.trust_level,
            },
        },
        prefix="lib-preview-v1",
    )


def _source_content_etag(
    *,
    actor,
    membership_role,
    item,
    version,
    blob,
    media_type,
):
    return _opaque_etag(
        {
            "schema": "library-preview-source-v1",
            "actor": _actor_etag_facts(actor, membership_role),
            "association": {
                "workspace_id": str(item.workspace_id),
                "item_id": str(item.id),
                "version_id": str(version.id),
                "blob_id": str(blob.blob_id),
                "blob_epoch": blob.epoch.value,
                "format_id": version.format_id,
                "media_type": media_type,
                "current_version_id": _str_or_none(item.current_version_id),
                "current_ready_version_id": _str_or_none(
                    item.current_ready_version_id
                ),
                "current_preview_version_id": _str_or_none(
                    item.current_preview_version_id
                ),
                "lifecycle_status": item.lifecycle_status,
                "trust_level": item.trust_level,
            },
        },
        prefix="lib-preview-source-v1",
    )


def _actor_etag_facts(actor, membership_role):
    return {
        "actor_kind": actor.actor_kind,
        "actor_id": actor.actor_id,
        "user_id": _str_or_none(actor.user_id),
        "workspace_id": _str_or_none(actor.workspace_id),
        "workspace_role": actor.workspace_role,
        "role": actor.role,
        "membership_role": membership_role,
        "scopes": sorted(actor.scopes),
        "token_kind": actor.token_kind,
        "token_id": _str_or_none(actor.token_id),
        "client_id": actor.client_id,
        "token_workspace_ids": sorted(
            str(workspace_id) for workspace_id in actor.token_workspace_ids
        ),
        "provenance": actor.provenance,
    }


def _opaque_etag(facts, *, prefix):
    encoded = json.dumps(
        facts,
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")
    return f'"{prefix}-{hashlib.sha256(encoded).hexdigest()[:32]}"'


def _security_blocked(session: Session, reference: BlobReference) -> bool:
    return (
        session.get(
            SecurityBlockedBlobRow,
            {
                "workspace_id": reference.workspace_id,
                "blob_id": reference.blob_id,
                "blob_epoch": reference.epoch.value,
            },
        )
        is not None
    )


def _source_content_url(workspace_id, version_id):
    return (
        f"/api/v1/workspaces/{workspace_id}/library/versions/{version_id}"
        "/preview/source"
    )


def _artifact_content_url(workspace_id, artifact_id):
    # P9.2: conversion, preview-generation and semantic-artifact content all
    # unify onto this one flat family -- see
    # ``library_canonical.canonical_library_artifact_lookup``.
    return f"/api/v1/workspaces/{workspace_id}/library/artifacts/{artifact_id}/content"


def _semantic_overlay_content_url(workspace_id, overlay_id):
    return (
        f"/api/v1/workspaces/{workspace_id}/library/semantic-overlays/"
        f"{overlay_id}/content"
    )


def _str_or_none(value):
    return str(value) if value is not None else None


__all__ = [
    "LibraryPreviewManifestService",
    "PreviewManifestProjection",
    "PreviewVariantProjection",
]
